    @Composable fun summary(): String = if (summaryRes == 0) "" else stringResource(summaryRes)
}

internal fun bottomNavSetting(tab: takagi.ru.monica.data.BottomNavContentTab): Setting = when (tab) {
    takagi.ru.monica.data.BottomNavContentTab.VAULT_V2 -> Setting.NAV_V2_VAULT
    takagi.ru.monica.data.BottomNavContentTab.PASSWORDS -> Setting.NAV_PASSWORDS
    takagi.ru.monica.data.BottomNavContentTab.AUTHENTICATOR -> Setting.NAV_AUTHENTICATOR
    takagi.ru.monica.data.BottomNavContentTab.CARD_WALLET -> Setting.NAV_CARD_WALLET
    takagi.ru.monica.data.BottomNavContentTab.GENERATOR -> Setting.NAV_GENERATOR
    takagi.ru.monica.data.BottomNavContentTab.NOTES -> Setting.NAV_NOTES
    takagi.ru.monica.data.BottomNavContentTab.PASSKEY -> Setting.NAV_PASSKEY
    takagi.ru.monica.data.BottomNavContentTab.SEND -> Setting.NAV_V2_SEND
    takagi.ru.monica.data.BottomNavContentTab.STEAM -> Setting.NAV_STEAM
}
